package com.finance.integration;
import com.fasterxml.jackson.databind.JsonNode;
import com.finance.common.exception.BusinessException;
import com.finance.service.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.client.TestRestTemplate;
import org.springframework.http.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties="app.recurring.enabled=false")
@EnabledIfEnvironmentVariable(named="FINANCE_INTEGRATION_DB_URL",matches=".+")
class AdminSecurityIntegrationTest {
    @Autowired TestRestTemplate client;@Autowired JdbcTemplate jdbc;@Autowired AdminService admin;@Autowired RecurringService recurring;
    @DynamicPropertySource static void database(DynamicPropertyRegistry p){String url=System.getenv("FINANCE_INTEGRATION_DB_URL");if(url==null||!url.matches("jdbc:mysql://[^/]+/finance_quality_test_[a-zA-Z0-9_]+(?:\\?.*)?"))throw new IllegalArgumentException("Isolated database required");p.add("spring.datasource.url",()->url);p.add("spring.datasource.username",()->"root");p.add("spring.datasource.password",()->System.getenv("FINANCE_INTEGRATION_DB_PASSWORD"));p.add("jwt.secret",()->"integration-test-only-secret-at-least-32-characters");p.add("app.avatar.storage-dir",()->"./target/integration-avatars");}
    @BeforeEach void isolation(){assertTrue(jdbc.queryForObject("SELECT DATABASE()",String.class).startsWith("finance_quality_test_"));}
    @Test void securityChainReturnsHttp403ToUsersAndHttp401WithoutToken(){Session u=session(false),a=session(true);for(String path:Arrays.asList("users","default-categories","dictionaries","logs","settings")){ResponseEntity<JsonNode> r=response(u,HttpMethod.GET,"/api/admin/"+path,null);assertEquals(403,r.getStatusCodeValue());assertEquals(403,r.getBody().path("code").asInt());}assertEquals(401,response(null,HttpMethod.GET,"/api/bill/recent",null).getStatusCodeValue());JsonNode users=call(a,HttpMethod.GET,"/api/admin/users",null);ok(users);assertFalse(users.path("data").path("records").get(0).has("password"));assertFalse(users.path("data").path("records").get(0).has("tokenVersion"));assertEquals(400,call(a,HttpMethod.GET,"/api/admin/users?size=101",null).path("code").asInt());}
    @Test void disablingRevokesExistingTokenAndStopsRecurringUntilReenabled(){Session u=session(false),a=session(true);long account=account(u,"CASH");ok(call(u,HttpMethod.POST,"/api/recurring",fields("name","Recurring","type",1,"categoryId",1,"accountId",account,"amount","1","frequency","DAILY","startDate",RecurringService.today().toString())));ok(call(a,HttpMethod.PUT,"/api/admin/users/"+u.id,fields("role","USER","status","DISABLED")));assertEquals(401,response(u,HttpMethod.GET,"/api/user/info",null).getStatusCodeValue());assertEquals(401,login(u).path("code").asInt());assertEquals(0,recurring.runDue(u.id,RecurringService.today()).get("generated"));ok(call(a,HttpMethod.PUT,"/api/admin/users/"+u.id,fields("role","USER","status","ACTIVE")));assertEquals(401,response(u,HttpMethod.GET,"/api/bill/recent",null).getStatusCodeValue());ok(login(u));assertEquals(1,recurring.runDue(u.id,RecurringService.today()).get("generated"));}
    @Test void adminCannotRemoveOwnAccessAndConcurrentRevocationsKeepOneActorActive()throws Exception{Session a=session(true),b=session(true);assertEquals(409,call(a,HttpMethod.PUT,"/api/admin/users/"+a.id,fields("role","USER","status","DISABLED")).path("code").asInt());ExecutorService pool=Executors.newFixedThreadPool(2);try{CountDownLatch start=new CountDownLatch(1);Future<Integer> first=pool.submit(()->revoke(start,a.id,b.id)),second=pool.submit(()->revoke(start,b.id,a.id));start.countDown();List<Integer> result=Arrays.asList(first.get(30,TimeUnit.SECONDS),second.get(30,TimeUnit.SECONDS));assertEquals(1,Collections.frequency(result,200));assertEquals(1,Collections.frequency(result,403));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM `user` WHERE id IN (?,?) AND status='ACTIVE'",Integer.class,a.id,b.id));}finally{pool.shutdownNow();}}
    @Test void sharedCategoriesProtectBillsBudgetsAndRecurringAcrossUsers(){Session a=session(true),u=session(false);long account=account(u,"CASH"),billCategory=defaultCategory(a),budgetCategory=defaultCategory(a),planCategory=defaultCategory(a),unused=defaultCategory(a);ok(call(u,HttpMethod.POST,"/api/bill",fields("accountId",account,"categoryId",billCategory,"type",1,"amount","1","billDate",RecurringService.today().toString())));ok(call(u,HttpMethod.POST,"/api/budget",fields("categoryId",budgetCategory,"amount","100","month",RecurringService.today().toString().substring(0,7))));ok(call(u,HttpMethod.POST,"/api/recurring",fields("name","Plan","type",1,"categoryId",planCategory,"accountId",account,"amount","1","frequency","DAILY","startDate",RecurringService.today().toString())));for(long id:Arrays.asList(billCategory,budgetCategory,planCategory))assertEquals(409,call(a,HttpMethod.DELETE,"/api/admin/default-categories/"+id,null).path("code").asInt());ok(call(a,HttpMethod.DELETE,"/api/admin/default-categories/"+unused,null));assertEquals(403,call(u,HttpMethod.PUT,"/api/category",fields("id",billCategory,"name","Illegal","type",1,"sortOrder",1)).path("code").asInt());ok(call(a,HttpMethod.PUT,"/api/admin/default-categories",fields("id",billCategory,"name","Renamed shared "+billCategory,"type",1,"sortOrder",1)));}
    @Test void dictionaryDisablingBlocksNewAccountsAndRenamesAppearInSystemData(){Session a=session(true),u=session(false);long id=jdbc.queryForObject("SELECT id FROM system_dictionary WHERE kind='ACCOUNT_TYPE' AND code='CASH'",Long.class);String previous=jdbc.queryForObject("SELECT name FROM system_dictionary WHERE id=?",String.class,id);try{ok(call(a,HttpMethod.PUT,"/api/admin/dictionaries/"+id,fields("name","Cash dictionary test","enabled",false)));assertEquals(400,call(u,HttpMethod.POST,"/api/account",fields("name","Blocked","accountType","CASH","openingBalance","0","openingDate","2020-01-01")).path("code").asInt());assertTrue(call(u,HttpMethod.GET,"/api/system/dictionaries",null).toString().contains("Cash dictionary test"));long cny=jdbc.queryForObject("SELECT id FROM system_dictionary WHERE kind='CURRENCY' AND code='CNY'",Long.class);assertEquals(409,call(a,HttpMethod.PUT,"/api/admin/dictionaries/"+cny,fields("name","人民币","enabled",false)).path("code").asInt());}finally{ok(call(a,HttpMethod.PUT,"/api/admin/dictionaries/"+id,fields("name",previous,"enabled",true)));}}
    @Test void registrationSettingHasRealEffectAndProfileCannotEscalateRole(){Session a=session(true),u=session(false);JsonNode old=call(a,HttpMethod.GET,"/api/admin/settings",null).path("data");try{ok(call(a,HttpMethod.PUT,"/api/admin/settings",fields("siteName","Validation finance","registrationEnabled",false)));assertEquals(403,call(null,HttpMethod.POST,"/api/user/register",fields("username","closed_"+UUID.randomUUID().toString().substring(0,8),"password","Test123!")).path("code").asInt());assertEquals("Validation finance",call(u,HttpMethod.GET,"/api/system/settings",null).path("data").path("siteName").asText());}finally{ok(call(a,HttpMethod.PUT,"/api/admin/settings",fields("siteName",old.path("siteName").asText(),"registrationEnabled",old.path("registrationEnabled").asBoolean())));}ok(call(u,HttpMethod.PUT,"/api/user/profile",fields("role","ADMIN","status","ACTIVE","nickname","Safe")));assertEquals("USER",jdbc.queryForObject("SELECT `role` FROM `user` WHERE id=?",String.class,u.id));}
    @Test void auditKeepsFailureOutcomesWithoutPasswordsOrTokens(){Session a=session(true),u=session(false);ok(call(u,HttpMethod.POST,"/api/account",fields("name","Sensitive remark not recorded","accountType","BANK","openingBalance","0","openingDate","2020-01-01")));assertEquals(409,call(a,HttpMethod.PUT,"/api/admin/users/"+a.id,fields("role","USER","status","DISABLED")).path("code").asInt());List<Map<String,Object>> logs=jdbc.queryForList("SELECT method,route,outcome FROM operation_log WHERE actor_id IN (?,?)",a.id,u.id);String text=logs.toString();assertTrue(logs.stream().anyMatch(row->Integer.valueOf(409).equals(row.get("outcome"))));assertFalse(text.contains("Test123!"));assertFalse(text.contains(u.token));assertFalse(text.contains("Sensitive remark"));assertTrue(text.contains("{id}"));}
    @Test void accountDeletionCannotRemoveAdministratorButStillRevokesOrdinaryUser() {
        Session a=session(true), u=session(false);
        assertEquals(409,call(a,HttpMethod.DELETE,"/api/user/account",null).path("code").asInt());
        assertEquals(0,jdbc.queryForObject("SELECT deleted FROM `user` WHERE id=?",Integer.class,a.id));
        ok(call(u,HttpMethod.DELETE,"/api/user/account",null));
        assertEquals(401,response(u,HttpMethod.GET,"/api/user/info",null).getStatusCodeValue());
    }
    private int revoke(CountDownLatch start,long actor,long target)throws InterruptedException{start.await();try{admin.updateUser(actor,target,"ADMIN","DISABLED");return 200;}catch(BusinessException e){return e.getCode();}}
    private long defaultCategory(Session a){String name="shared_"+UUID.randomUUID().toString().substring(0,8);ok(call(a,HttpMethod.POST,"/api/admin/default-categories",fields("name",name,"type",1,"sortOrder",1)));return jdbc.queryForObject("SELECT id FROM category WHERE user_id=0 AND name=?",Long.class,name);}
    private long account(Session s,String type){String name="Account "+UUID.randomUUID().toString().substring(0,8);ok(call(s,HttpMethod.POST,"/api/account",fields("name",name,"accountType",type,"openingBalance","100","openingDate","2020-01-01")));return jdbc.queryForObject("SELECT id FROM finance_account WHERE user_id=? AND name=?",Long.class,s.id,name);}
    private Session session(boolean admin){Session s=new Session();s.name="p4_"+UUID.randomUUID().toString().substring(0,12);ok(call(null,HttpMethod.POST,"/api/user/register",fields("username",s.name,"password","Test123!","role","ADMIN")));JsonNode r=login(s);ok(r);s.id=r.path("data").path("userId").asLong();s.token=r.path("data").path("token").asText();assertEquals("USER",r.path("data").path("role").asText());if(admin){jdbc.update("UPDATE `user` SET `role`='ADMIN' WHERE id=?",s.id);r=login(s);ok(r);s.token=r.path("data").path("token").asText();assertEquals("ADMIN",r.path("data").path("role").asText());}return s;}
    private JsonNode login(Session s){return call(null,HttpMethod.POST,"/api/user/login",fields("username",s.name,"password","Test123!"));}
    private ResponseEntity<JsonNode> response(Session s,HttpMethod m,String path,Object body){HttpHeaders h=new HttpHeaders();h.setContentType(MediaType.APPLICATION_JSON);if(s!=null)h.setBearerAuth(s.token);return client.exchange(path,m,new HttpEntity<>(body,h),JsonNode.class);}
    private JsonNode call(Session s,HttpMethod m,String path,Object body){return response(s,m,path,body).getBody();}
    private void ok(JsonNode r){assertNotNull(r);assertEquals(200,r.path("code").asInt());}
    private static Map<String,Object> fields(Object...p){Map<String,Object> r=new HashMap<>();for(int i=0;i<p.length;i+=2)r.put((String)p[i],p[i+1]);return r;}
    private static class Session{long id;String name,token;}
}
